head.script:
scwin.unitTest = function() {
    //Unit test
    WebSquare.wUnit.start();
	WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('inputCalendar5_img').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('inputCalendar5_calendar_last_year').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "document.getElementsByClassName('w2calendar_header_last_month')[0].click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "document.getElementsByClassName('w2calendar_header_next_month')[0].click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "document.getElementsByClassName('w2calendar_header_next_year')[0].click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('inputCalendar5_calendar_selectbox_year_button').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('inputCalendar5_calendar_selectbox_year_itemTable_39').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('inputCalendar5_calendar_selectbox_month_button').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('inputCalendar5_calendar_selectbox_month_itemTable_3').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('inputCalendar5_calendar_cell_2_4').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('inputCalendar5_calendar_selectbox_hour_button').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('inputCalendar5_calendar_selectbox_hour_itemTable_3').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('inputCalendar5_calendar_selectbox_minute_button').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('inputCalendar5_calendar_selectbox_minute_itemTable_4').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('inputCalendar5_calendar_selectbox_second_button').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('inputCalendar5_calendar_selectbox_second_itemTable_7').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getJq('.w2calendar_time_confirm')[0].click()");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('inputCalendar5_input').blur()");
    WebSquare.wUnit.addCommand("pause", "500");
    //Verify 3. 선택한 년/월 (시간) 이 등록된다. (그전버전에서는 skipConfirm='true' 시 확인버튼이 나오지 않아서 한번 더 월을 선택해야하는 번거로움이 있었음.)
    //3. The selected year / month (hour) is registered. (In previous versions, skipConfirm = 'true' did not come up with confirmation button, so I had to choose one more month.)
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getDomById('inputCalendar5_input').value == '2017-04-13 03:04:07'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run and Stop test
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.unitTest();
scwin.onpageload = function() {
}
